import { parseCommandLine } from './lib/cli.mjs';
import { alabel, decode, encode, ulabel } from './lib/idna/index.mjs';

function bytesLiteral(text) {
  return `b'${text.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

function writeLine(stream, text) {
  stream.write(`${text}\n`);
}

const parsed = parseCommandLine(process.argv.slice(2), process.argv[1]);

if (!parsed.ok) {
  const stream = parsed.stream === 'stderr' ? process.stderr : process.stdout;
  stream.write(parsed.text);
  process.exit(parsed.exitCode);
}

const domain = parsed.domain;
const encoded = encode(domain);
writeLine(process.stdout, bytesLiteral(encoded));

const decoded = decode(encoded);
writeLine(process.stdout, decoded);

const firstLabel = domain.split('.')[0];
if (firstLabel) {
  const ulabelResult = ulabel(encode(firstLabel));
  writeLine(process.stdout, ulabelResult);

  const alabelResult = alabel(firstLabel);
  writeLine(process.stdout, bytesLiteral(alabelResult));
}

