import { IDNAError } from '../errors.mjs';

const BASE = 36;
const T_MIN = 1;
const T_MAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;
const DELIMITER = '-';

function adapt(delta, numPoints, firstTime) {
  let value = firstTime ? Math.floor(delta / DAMP) : Math.floor(delta / 2);
  value += Math.floor(value / numPoints);

  let k = 0;
  while (value > Math.floor(((BASE - T_MIN) * T_MAX) / 2)) {
    value = Math.floor(value / (BASE - T_MIN));
    k += BASE;
  }

  return k + Math.floor((((BASE - T_MIN + 1) * value) / (value + SKEW)));
}

function basicToDigit(codePoint) {
  if (codePoint >= 48 && codePoint <= 57) {
    return codePoint - 22;
  }

  if (codePoint >= 65 && codePoint <= 90) {
    return codePoint - 65;
  }

  if (codePoint >= 97 && codePoint <= 122) {
    return codePoint - 97;
  }

  return BASE;
}

function digitToBasic(digit) {
  return String.fromCharCode(digit + 22 + (digit < 26 ? 75 : 0));
}

export function encodePunycode(text) {
  const input = Array.from(text, (character) => character.codePointAt(0));
  let n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;
  let output = '';

  for (const codePoint of input) {
    if (codePoint < 0x80) {
      output += String.fromCodePoint(codePoint).toLowerCase();
    }
  }

  const basicLength = output.length;
  let handled = basicLength;

  if (basicLength > 0) {
    output += DELIMITER;
  }

  while (handled < input.length) {
    let nextCodePoint = Number.MAX_SAFE_INTEGER;

    for (const codePoint of input) {
      if (codePoint >= n && codePoint < nextCodePoint) {
        nextCodePoint = codePoint;
      }
    }

    delta += (nextCodePoint - n) * (handled + 1);
    n = nextCodePoint;

    for (const codePoint of input) {
      if (codePoint < n) {
        delta += 1;
      }

      if (codePoint !== n) {
        continue;
      }

      let q = delta;
      for (let k = BASE; ; k += BASE) {
        const t =
          k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;

        if (q < t) {
          break;
        }

        output += digitToBasic(t + ((q - t) % (BASE - t)));
        q = Math.floor((q - t) / (BASE - t));
      }

      output += digitToBasic(q);
      bias = adapt(delta, handled + 1, handled === basicLength);
      delta = 0;
      handled += 1;
    }

    delta += 1;
    n += 1;
  }

  return output;
}

export function decodePunycode(text) {
  let n = INITIAL_N;
  let i = 0;
  let bias = INITIAL_BIAS;
  const output = [];

  const delimiterIndex = text.lastIndexOf(DELIMITER);
  const basicLength = delimiterIndex === -1 ? 0 : delimiterIndex;

  for (let index = 0; index < basicLength; index += 1) {
    const codePoint = text.codePointAt(index);
    if (codePoint === undefined || codePoint >= 0x80) {
      throw new IDNAError('Invalid A-label');
    }

    output.push(String.fromCodePoint(codePoint).toLowerCase());
  }

  let index = delimiterIndex === -1 ? 0 : delimiterIndex + 1;

  while (index < text.length) {
    const oldI = i;
    let w = 1;

    for (let k = BASE; ; k += BASE) {
      if (index >= text.length) {
        throw new IDNAError('Invalid A-label');
      }

      const digit = basicToDigit(text.codePointAt(index));
      index += 1;

      if (digit >= BASE) {
        throw new IDNAError('Invalid A-label');
      }

      i += digit * w;
      const t =
        k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;

      if (digit < t) {
        break;
      }

      w *= (BASE - t);
    }

    const outputLength = output.length + 1;
    bias = adapt(i - oldI, outputLength, oldI === 0);
    n += Math.floor(i / outputLength);
    i %= outputLength;
    output.splice(i, 0, String.fromCodePoint(n));
    i += 1;
  }

  return output.join('');
}

