import { IDNABidiError, IDNAError, InvalidCodepoint } from '../errors.mjs';
import {
  findCodePointIndex,
  formatCodePoint,
  hasAcePrefix,
  isAscii,
  isCombiningMark,
  isLetter,
  isRtlLabel,
  isUppercaseLetter,
  isValidUnicodeCodePoint,
  startsWithRtlNumeral,
  toCodePoints,
} from './code-points.mjs';
import { decodePunycode, encodePunycode } from './punycode.mjs';

function throwInvalidCodepoint(label, character, position) {
  throw new InvalidCodepoint(
    `Codepoint ${formatCodePoint(character)} at position ${position} of '${label}' not allowed`,
  );
}

function checkLabelLength(label) {
  if (label.length > 63) {
    throw new IDNAError('Label too long');
  }
}

function checkHyphenRules(label, allowAcePrefix) {
  if (label.startsWith('-') || label.endsWith('-')) {
    throw new IDNAError('Label must not start or end with a hyphen');
  }

  if (!allowAcePrefix && label.length >= 4 && label[2] === '-' && label[3] === '-') {
    throw new IDNAError('Label has disallowed hyphens in 3rd and 4th position');
  }
}

function validateAsciiLabel(label) {
  checkHyphenRules(label, hasAcePrefix(label));

  const codePoints = toCodePoints(label);
  for (let index = 0; index < codePoints.length; index += 1) {
    const character = codePoints[index];
    if (!/^[A-Za-z0-9-]$/.test(character)) {
      throwInvalidCodepoint(label, character, index + 1);
    }
  }

  checkLabelLength(label);
}

function checkBidi(label) {
  if (!startsWithRtlNumeral(label) && !isRtlLabel(label)) {
    return;
  }

  const [first = ''] = toCodePoints(label);
  if (!isLetter(first)) {
    throw new IDNABidiError(
      `First codepoint in label '${label}' must be directionality L, R or AL`,
    );
  }
}

function validateUnicodeLabel(label) {
  checkHyphenRules(label, false);

  if (label.normalize('NFC') !== label) {
    throw new IDNAError('Label must be in Normalization Form C');
  }

  const [first = ''] = toCodePoints(label);
  if (isCombiningMark(first)) {
    throw new IDNAError('Label begins with an illegal combining character');
  }

  const codePoints = toCodePoints(label);
  for (let index = 0; index < codePoints.length; index += 1) {
    const character = codePoints[index];
    if (!isValidUnicodeCodePoint(character) || isUppercaseLetter(character)) {
      throwInvalidCodepoint(label, character, index + 1);
    }
  }

  checkBidi(label);
}

export function alabel(label) {
  if (label.length === 0) {
    throw new IDNAError('Empty Label');
  }

  if (isAscii(label)) {
    if (hasAcePrefix(label)) {
      ulabel(label);
      checkLabelLength(label);
      return label;
    }

    validateAsciiLabel(label);
    return label;
  }

  validateUnicodeLabel(label);
  const asciiLabel = `xn--${encodePunycode(label)}`;
  checkLabelLength(asciiLabel);
  return asciiLabel;
}

export function ulabel(label) {
  if (label.length === 0) {
    throw new IDNAError('Empty Label');
  }

  if (isAscii(label)) {
    if (hasAcePrefix(label)) {
      const payload = label.slice(4);
      if (payload.length === 0) {
        throw new IDNAError('Malformed A-label, no Punycode eligible content found');
      }

      const decoded = decodePunycode(payload);
      validateUnicodeLabel(decoded);
      return decoded;
    }

    validateAsciiLabel(label);
    return label.toLowerCase();
  }

  validateUnicodeLabel(label);
  return label;
}

