function ensureDomainLabels(labels, isEmptyDomain) {
  if (isEmptyDomain) {
    throw new IDNAError('Empty domain');
  }

  if (labels.some((label) => label.length === 0)) {
    throw new IDNAError('Empty Label');
  }
}

function checkDomainLength(domain) {
  const maxLength = domain.endsWith('.') ? 254 : 253;
  if (domain.length > maxLength) {
    throw new IDNAError('Domain too long');
  }
}

export function encode(domain) {
  const { labels, trailingDot } = splitDomain(domain);
  ensureDomainLabels(labels, domain.length === 0);

  const asciiDomain = labels.map((label) => alabel(label)).join('.') + (trailingDot ? '.' : '');
  checkDomainLength(asciiDomain);
  return asciiDomain;
}

export function decode(domain) {
  const { labels, trailingDot } = splitDomain(domain);
  ensureDomainLabels(labels, domain.length === 0);

  return labels.map((label) => ulabel(label)).join('.') + (trailingDot ? '.' : '');
}

